fas_manifest_example:
{
  "name": "send_email",
  "params": [
    {
      "name": "to",
      "type": "string",
      "required": true,
      "coercion": "permissive",
      "examples": ["alice@example.com", "+1-415-555-1234"],
      "description": "Recipient address - email or phone. SDKs should normalize and validate formats."
    },
    {
      "name": "body",
      "type": "string",
      "required": false,
      "coercion": "strict",
      "requires_auth": false,
      "description": "Message body in plain text."
    },
    {
      "name": "priority",
      "type": "enum",
      "values": ["low", "normal", "high"],
      "required": false,
      "default": "normal"
    }
  ]
}

diagnostic_envelope_example:
